package dev.jarofcucumbers.prscraft;
import net.minecraft.nbt.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import java.util.*;
/** Bounded editable laboratory. Nodes keep the actual block-entity NBT; edges stand for port-cable-port. */
public final class SimulatorDocument{
    private CompoundTag data;
    public SimulatorDocument(){data=new CompoundTag();data.put("nodes",new ListTag());data.put("wires",new ListTag());data.putString("weather","dry");}
    public SimulatorDocument(CompoundTag saved){data=saved.copy();validate();}
    public CompoundTag save(){return data.copy();}public ListTag nodes(){return data.getList("nodes",10);}public ListTag wires(){return data.getList("wires",10);}
    public static boolean allowed(String kind){var block=BuiltInRegistries.BLOCK.get(ResourceLocation.fromNamespaceAndPath(PRSCraft.ID,kind));return block instanceof TransmitterBlock||block instanceof DrawingBoardBlock;}
    public CompoundTag node(int id){for(int i=0;i<nodes().size();i++)if(nodes().getCompound(i).getInt("id")==id)return nodes().getCompound(i);throw new IllegalArgumentException("sim_node");}
    private void validate(){if(nodes().size()>32||wires().size()>64||!Set.of("dry","rain","snow").contains(data.getString("weather")))throw new IllegalArgumentException("sim_limit");Set<Integer> ids=new HashSet<>();for(int i=0;i<nodes().size();i++){var n=nodes().getCompound(i);if(n.getInt("id")<0||n.getInt("id")>=32||!ids.add(n.getInt("id"))||!allowed(n.getString("kind")))throw new IllegalArgumentException("sim_node");coordinate(n.getDouble("x"));coordinate(n.getDouble("y"));var dir=Direction.byName(n.getString("facing"));if(dir==null||dir.getAxis().isVertical())throw new IllegalArgumentException("sim_node");}Set<String> endpoints=new HashSet<>();for(int i=0;i<wires().size();i++){var w=wires().getCompound(i);if(!ids.contains(w.getInt("from"))||!ids.contains(w.getInt("to"))||w.getInt("from")==w.getInt("to")||!Set.of("A","B").contains(w.getString("input"))||!endpoints.add(w.getInt("to")+w.getString("input")))throw new IllegalArgumentException("sim_wire");settings(w);SignalBudget.Medium.valueOf(w.getString("medium"));}}
    private static void coordinate(double v){if(!Double.isFinite(v)||Math.abs(v)>8192)throw new IllegalArgumentException("sim_position");}
    public int add(String kind,double x,double y){if(!allowed(kind)||nodes().size()>=32)throw new IllegalArgumentException("sim_node");coordinate(x);coordinate(y);int id=0;Set<Integer> used=new HashSet<>();for(int i=0;i<nodes().size();i++)used.add(nodes().getCompound(i).getInt("id"));while(used.contains(id))id++;var n=new CompoundTag();n.putInt("id",id);n.putString("kind",kind);n.putString("facing","east");n.putDouble("x",x);n.putDouble("y",y);n.put("state",new CompoundTag());nodes().add(n);return id;}
    public void move(int id,double x,double y){coordinate(x);coordinate(y);var n=node(id);n.putDouble("x",x);n.putDouble("y",y);}
    public void remove(int id){node(id);nodes().removeIf(t->((CompoundTag)t).getInt("id")==id);wires().removeIf(t->((CompoundTag)t).getInt("from")==id||((CompoundTag)t).getInt("to")==id);}
    public void weather(String value){if(!Set.of("dry","rain","snow").contains(value))throw new IllegalArgumentException("environment");data.putString("weather",value);}
    public void wire(int from,int to,String input,SignalBudget.Medium medium,CableSettings settings){node(from);node(to);if(from==to||!Set.of("A","B").contains(input))throw new IllegalArgumentException("sim_wire");var list=wires();list.removeIf(t->((CompoundTag)t).getInt("to")==to&&((CompoundTag)t).getString("input").equals(input));if(list.size()>=64)throw new IllegalArgumentException("sim_limit");var w=new CompoundTag();w.putInt("from",from);w.putInt("to",to);w.putString("input",input);w.putString("medium",medium.name());w.putDouble("metres",settings.metres());w.putDouble("damage",settings.damage());w.putDouble("dispersion",settings.dispersion());w.putBoolean("environment",settings.environment());list.add(w);}
    public static CableSettings settings(CompoundTag w){return new CableSettings(w.getDouble("metres"),w.getDouble("damage"),w.getDouble("dispersion"),!w.contains("environment")||w.getBoolean("environment"));}
    public static BlockPos position(int id){return new BlockPos(id*3,0,0);}
    public World world(HolderLookup.Provider registries,long tick){return new World(registries,tick);}
    public final class World implements CircuitAccess{
        private final Map<BlockPos,BlockEntity> blocks=new HashMap<>();private final HolderLookup.Provider registries;private final long tick;
        World(HolderLookup.Provider registries,long tick){this.registries=registries;this.tick=tick;for(int i=0;i<nodes().size();i++){var n=nodes().getCompound(i);var block=BuiltInRegistries.BLOCK.get(ResourceLocation.fromNamespaceAndPath(PRSCraft.ID,n.getString("kind")));BlockState state=block.defaultBlockState().setValue(net.minecraft.world.level.block.HorizontalDirectionalBlock.FACING,Direction.byName(n.getString("facing")));var pos=position(n.getInt("id"));BlockEntity entity=((EntityBlock)block).newBlockEntity(pos,state);entity.loadWithComponents(n.getCompound("state"),registries);blocks.put(pos,entity);}}
        public void persist(){for(int i=0;i<nodes().size();i++){var n=nodes().getCompound(i);n.put("state",blocks.get(position(n.getInt("id"))).saveWithoutMetadata(registries));}}
        public boolean physicalInterference(){return false;}
        public boolean hasChunkAt(BlockPos pos){return blocks.containsKey(pos);}public BlockState getBlockState(BlockPos pos){return blocks.containsKey(pos)?blocks.get(pos).getBlockState():Blocks.AIR.defaultBlockState();}public BlockEntity getBlockEntity(BlockPos pos){return blocks.get(pos);}public long getGameTime(){return tick;}
        public List<CircuitNetwork.Route> routes(BlockPos root,Direction side,Double carrier){var result=new ArrayList<CircuitNetwork.Route>();if(!(getBlockEntity(root) instanceof RadioBlockEntity target))return result;for(int i=0;i<wires().size();i++){var wire=wires().getCompound(i);if(!position(wire.getInt("to")).equals(root))continue;var direction=wire.getString("input").equals("B")?target.getBlockState().getValue(TransmitterBlock.FACING).getCounterClockWise():target.getBlockState().getValue(TransmitterBlock.FACING).getOpposite();if(side!=null&&side!=direction)continue;if(wire.getString("input").equals("B")&&!Set.of("adder","correlator","orthogonality_meter").contains(target.kind()))continue;var pos=position(wire.getInt("from"));if(!(getBlockEntity(pos) instanceof RadioBlockEntity source)||!source.settings().enabled()||source.isSource()&&!source.settings().transmit()||carrier!=null&&source.isSource()&&Math.abs(carrier-source.settings().carrierMHz())>.001)continue;var medium=SignalBudget.Medium.valueOf(wire.getString("medium"));var cfg=settings(wire);var env=cfg.environment()?EnvironmentEffect.model(medium,cfg.metres(),data.getString("weather").equals("rain"),data.getString("weather").equals("snow"),0,0,0,0):EnvironmentEffect.NONE;double loss=medium.lossDb(cfg.metres(),carrier==null?source.settings().carrierMHz():carrier)+medium.lossDb(0,carrier==null?source.settings().carrierMHz():carrier)+cfg.extraLossDb()+env.lossDb();result.add(new CircuitNetwork.Route(pos,cfg.metres(),loss,cfg.noiseVariance()+env.variance(),cfg.extraLossDb(),medium,List.of(),cfg.metres()*cfg.dispersion(),env.lossDb(),env.variance()));}return result;}
    }
}
